// shepherd — this repo's own rules: the ones that are true here and portable nowhere.
// Seeded empty at adoption; everything in it is this repo's to write. A lesson that
// would hold in another repo belongs in a canon pack instead — propose it upstream.
// worldRules is discovered structurally from worldRules/*.mjs — leave it unspoken
// here so a coded rule module is picked up without also touching this manifest.
export default {
  id: 'shepherd',
  version: 1,
  ruleRoutingGuidance: {
    belongs: 'working rules and lessons specific to this repository and not portable to any other',
    excludes: 'anything true beyond this repo — that belongs in a canon pack, proposed upstream',
  },
  detect: null,
  marker: null,
  prose: 'RULES.md',
};
===CHECKS===
[
  {
    "id": "branch-from-local-main",
    "severity": "blocking",
    "since": "2026-09-13",
    "scope": "action",
    "failureMessage": "this checkout's local main can sit pinned at the repo's very first commit, so branching from it silently starts from frozen history",
    "guardToolCalls": [
      {
        "tool": "Bash",
        "inputField": "command",
        "match": "/git\\s+(?:checkout\\s+-b|branch)\\s+\\S+\\s+main\\b/",
        "what": "a git branch created from bare \"main\" (\"{match}\")",
        "fix": "git fetch origin main, then branch from origin/main explicitly"
      }
    ]
  }
]

